import { expect, test, uniqueName, sample } from "../../fixtures";

const W9 = "Legal Name: Acme Freight LLC\nTax ID: 12-3456789\nBusiness Type: LLC\n";
const CONTRACT = "Counterparty: Acme Freight LLC\nEffective Date: 2026-01-01\nExpiry Date: 2027-12-31\n";

function isoDateDaysFromNow(days: number): string {
  const d = new Date();
  d.setDate(d.getDate() + days);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function insuranceText(expiry: string): string {
  return `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;
}

test("an expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const yesterday = isoDateDaysFromNow(-1);

  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Expired Cert Co"), category: "logistics", contact_email: "ops@expired-cert.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  const uploads: Array<{ kind: string; text: string }> = [
    { kind: "w9", text: W9 },
    { kind: "insurance_certificate", text: insuranceText(yesterday) },
    { kind: "contract", text: CONTRACT },
  ];
  for (const { kind, text } of uploads) {
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) },
      },
    });
    expect(res.status(), await res.text()).toBe(201);
  }

  // Wait for background extraction of every document.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await res.json()) as Array<{ status: string }>;
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 30_000 },
    )
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);

  // Locate the insurance certificate extraction.
  const docsRes = await member.get(`/api/vendors/${vendor.id}/documents`);
  expect(docsRes.status(), await docsRes.text()).toBe(200);
  const docs = (await docsRes.json()) as Array<{ id: string; kind: string }>;
  const insurance = docs.find((d) => d.kind === "insurance_certificate");
  expect(insurance, JSON.stringify(docs)).toBeDefined();

  const extractionRes = await member.get(`/api/documents/${insurance!.id}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const extraction = (await extractionRes.json()) as { id: string; fields: Record<string, { value: string | null }> };
  expect(extraction.fields.expiry_date.value, JSON.stringify(extraction.fields)).toBe(yesterday);

  // Act
  const decision = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  expect(decision.status(), await decision.text()).toBe(409);
  const body = (await decision.json()) as { error: { code: string } };
  expect(body.error.code, JSON.stringify(body)).toBe("insurance_expired");
});
